export const handler = async (event) => {
  if (Array.isArray(event.Records)) {
    const bodies = event.Records.map((record) => record.body);
    console.log(JSON.stringify({ level: "INFO", message: "SQS batch received", recordCount: bodies.length }));
    if (bodies.includes("fail")) {
      console.error(JSON.stringify({ level: "ERROR", message: "Intentional training failure" }));
      throw new Error("Intentional training failure");
    }
    console.log(JSON.stringify({ level: "INFO", message: "SQS batch processed", bodies }));
    return { processedRecords: bodies.length };
  }

  if (typeof event.length === "number" && typeof event.width === "number") {
    const area = event.length * event.width;
    console.log(JSON.stringify({ level: "INFO", message: "Area calculated", area }));
    return { statusCode: 200, body: JSON.stringify({ area }) };
  }

  const path = event.rawPath || event.requestContext?.http?.path || "/";
  console.log(JSON.stringify({ level: "INFO", message: "HTTP request processed", path }));
  return {
    statusCode: 200,
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ message: "Lambda HTTP endpoint is working", path })
  };
};
